"""Summarize mailtodo letters without changing the input tree."""
import argparse
from datetime import datetime, timedelta
import json
from pathlib import Path
import re

NAME = re.compile(r"^(\d{8}T\d{4})[-_]")
RESOLVED = {"DONE", "BLOCKED", "NEEDS-USER", "FAILED"}
REQUIRED = ("id", "from", "to", "status", "at")


def letter(path, now):
    try:
        lines = path.read_text(encoding="utf-8").split("\n")
    except (OSError, UnicodeError):
        return None, "no_frontmatter"
    lines = [line[:-1] if line.endswith("\r") else line for line in lines]
    if not lines or lines[0] != "---":
        return None, "no_frontmatter"
    try:
        end = lines.index("---", 1)
    except ValueError:
        return None, "no_frontmatter"
    fields = {}
    for line in lines[1:end]:
        if ": " in line:
            key, value = line.split(": ", 1)
            fields[key] = value
    if not all(fields.get(key) for key in REQUIRED):
        return None, "no_field"
    try:
        at = datetime.fromisoformat(fields["at"])
    except (ValueError, OverflowError):
        return None, "no_field"
    if at.tzinfo is None:
        at = at.replace(tzinfo=now.tzinfo)
    match = NAME.match(path.name)
    if match is None:
        return None, "bad_name"
    try:
        datetime.strptime(match.group(1), "%Y%m%dT%H%M")
    except ValueError:
        return None, "bad_name"
    fields["at"] = at
    return fields, None


def summarize(root, now):
    boxes = {}
    paths = []
    for mailbox in sorted(root.iterdir()):
        if mailbox.name.startswith(".") or mailbox.is_symlink() or not mailbox.is_dir():
            continue
        inbox = mailbox / "inbox"
        if inbox.is_symlink() or not inbox.is_dir():
            continue
        boxes[mailbox.name] = {"inbox": {}, "done": 0}
        for directory in (inbox, inbox / "done"):
            if directory.is_symlink() or not directory.is_dir():
                continue
            paths.extend(path for path in directory.iterdir()
                         if not path.name.startswith(".") and not path.is_symlink()
                         and path.is_file() and path.suffix == ".md")
    valid = []
    bad = []
    seen = set()
    for path in sorted(paths, key=lambda item: item.relative_to(root).as_posix()):
        relative = path.relative_to(root).as_posix()
        fields, why = letter(path, now)
        if why is None and fields["id"] in seen:
            why = "dup_id"
        if why is not None:
            bad.append({"file": relative, "why": why})
            continue
        seen.add(fields["id"])
        where = "done" if path.parent.name == "done" else "inbox"
        box = boxes[path.relative_to(root).parts[0]]
        if where == "done":
            box["done"] += 1
        else:
            counts = box["inbox"]
            counts[fields["status"]] = counts.get(fields["status"], 0) + 1
        valid.append((fields, where))
    resolved = {fields.get("re") for fields, _ in valid
                if fields["status"] in RESOLVED and fields.get("re")}
    opened = [{"id": fields["id"], "from": fields["from"],
               "to": fields["to"], "where": where,
               "age_min": (now - fields["at"]) // timedelta(minutes=1)}
              for fields, where in valid
              if fields["status"] == "REQUEST" and fields["id"] not in resolved]
    opened.sort(key=lambda item: (item["to"], item["id"]))
    bad.sort(key=lambda item: (item["file"], item["why"]))
    return {"v": 1, "open": opened, "boxes": boxes, "bad": bad}


def main(argv=None):
    parser = argparse.ArgumentParser(description="Read-only mailtodo summary")
    parser.add_argument("folder", type=Path)
    parser.add_argument("--now", required=True)
    args = parser.parse_args(argv)
    try:
        now = datetime.fromisoformat(args.now)
    except (ValueError, TypeError):
        parser.error("--now must be an ISO timestamp with a timezone")
    if now.tzinfo is None:
        parser.error("--now must include a timezone")
    if not args.folder.is_dir():
        parser.error("folder must be a directory")
    print(json.dumps(summarize(args.folder, now), ensure_ascii=False,
                     separators=(",", ":")))
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
